### Python

```python
import sys
from itertools import permutations, product


# 实现向零取整的整数除法
def trunc_div(x, y):
    # 题目中 a_i 都是正整数，因此 y 一定大于 0
    if x >= 0:
        return x // y
    else:
        return -((-x) // y)


# 判断当前测试用例是否能得到 24
def can_make_24(nums):
    n = len(nums)

    # 枚举所有重排
    for perm in permutations(nums):
        # 枚举每一步选择的运算，0/1/2/3 分别表示 + - * /
        for ops in product(range(4), repeat=n - 1):
            cur = perm[0]

            # 按严格左结合顺序依次计算
            for i in range(n - 1):
                x = perm[i + 1]
                op = ops[i]

                if op == 0:
                    cur = cur + x
                elif op == 1:
                    cur = cur - x
                elif op == 2:
                    cur = cur * x
                else:
                    cur = trunc_div(cur, x)

            # 若最终结果为 24，则存在可行方案
            if cur == 24:
                return True

    return False


def main():
    input = sys.stdin.readline
    T = int(input().strip())

    for _ in range(T):
        n = int(input().strip())
        nums = list(map(int, input().split()))

        if can_make_24(nums):
            print("Yes")
        else:
            print("No")


if __name__ == "__main__":
    main()
```

