    public static boolean canMake24(int[] nums) {
        int n = nums.length;
        boolean[] used = new boolean[n];
        int[] perm = new int[n];

        // 先枚举所有重排
        return dfsPerm(nums, used, perm, 0);
    }

    // 深度优先搜索枚举排列
    public static boolean dfsPerm(int[] nums, boolean[] used, int[] perm, int idx) {
        int n = nums.length;

        // 一个排列构造完成后，继续枚举所有运算方式
        if (idx == n) {
            return dfsOps(perm, 1, perm[0]);
        }

        for (int i = 0; i < n; i++) {
            if (!used[i]) {
                used[i] = true;
                perm[idx] = nums[i];

                if (dfsPerm(nums, used, perm, idx + 1)) {
                    return true;
                }

                used[i] = false;
            }
        }

        return false;
    }

    // 深度优先搜索枚举每一步的运算符
    public static boolean dfsOps(int[] perm, int pos, int cur) {
        int n = perm.length;

        // 所有数字都用完后，判断是否得到 24
        if (pos == n) {
            return cur == 24;
        }

        int x = perm[pos];

        // 依次尝试 +、-、*、/
        if (dfsOps(perm, pos + 1, cur + x)) {
            return true;
        }
        if (dfsOps(perm, pos + 1, cur - x)) {
            return true;
        }
        if (dfsOps(perm, pos + 1, cur * x)) {
            return true;
        }
        // Java 的整数除法本身就是向零取整
        if (dfsOps(perm, pos + 1, cur / x)) {
            return true;
        }

        return false;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int T = sc.nextInt();
        while (T-- > 0) {
            int n = sc.nextInt();
            int[] nums = new int[n];

            for (int i = 0; i < n; i++) {
                nums[i] = sc.nextInt();
            }

            if (canMake24(nums)) {
                System.out.println("Yes");
            } else {
                System.out.println("No");
            }
        }

        sc.close();
    }
}
